\Longleftrightarrow\;
(2)\; &\exists (x_n)\subseteq A:\; x_n \to c \land \neg\bigl(f(x_n)\to f(c)\bigr)\\
\Longleftrightarrow\;
(3)\; &\exists V \text{ nbhd of } f(c)\;\forall U \text{ nbhd of } c\;\exists x\in U\cap A:\;f(x)\notin V.
\end{aligned}
\]

